texts = ROOT / "texts.js"
s = texts.read_text()
for lang, values in T.items():
    assert len(values) == len(KEYS), (lang, len(values))
    nls = json.loads((EXT / NLS[lang]).read_text())
    values = [v.replace("{cmd.addLanguage}", nls["cmd.addLanguage"].rstrip("…")).replace("{cmd.open}", nls["cmd.open"])
              .replace("{cmd.test}", nls["cmd.test"]).replace("{cmd.showLog}", nls["cmd.showLog"]) for v in values]
    head = f'TEXTS.{lang} = {{' if "-" not in lang else f'TEXTS["{lang}"] = {{'
    a = s.index(head); b = s.index("\n};", a)
    block = "\n".join(l for l in s[a:b].split("\n") if not any(l.lstrip().startswith(k + ":") for k in KEYS)).rstrip()
    if not block.endswith(","):
        block += ","
    block += "\n" + "\n".join(f"  {k}: {json.dumps(v, ensure_ascii=False)}," for k, v in zip(KEYS, values))
    s = s[:a] + block + s[b:]
texts.write_text(s)
print("ok")
